# WAR ARENA — Founder Wallet Follow function (spec Rule 5): follow + real follower count
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-founder-follow.ps1
$ErrorActionPreference = 'Stop'
Write-Host 'Installing Founder Wallet follow...' -ForegroundColor Cyan

if (-not (Test-Path 'migrations')) { New-Item -ItemType Directory -Force -Path 'migrations' | Out-Null }
